def conv(a, b):
 N = len(a)
 M = len(b)
 YN = N + M - 1
 y = [0.0 for i in range(YN)]
 for n in range(YN):
 for m in range(M):
 if 0 <= n - m and n - m < N:
 y[n] += a[n - m] * b[m]
 return y
